# Batch 2 school pages (facts checked 2026-11-11 against the sources listed on each page).
from schools import S, timeline, standout, CTA

def mk(slug, name, full, desc, lede, cards, extra, qas, src, related=None):
    return {"slug": f"{slug}-investment-banking", "short": f"Investment banking from {name}",
        "title": f"How to Get Into Investment Banking From {name}" + (f" ({full})" if full else ""),
        "h1": f"How to get into investment banking from {name}", "desc": desc,
        "related": related or ["investment-banking-recruiting-timeline", "investment-banking-interview-questions", "ohio-state-investment-banking"],
        "lede": lede,
        "body": [("h2", "Programs and clubs to know"), *[("card", *c) for c in cards], *timeline(name), *standout(extra),
                 ("h2", "Common questions"), *[("qa", q, a) for q, a in qas], CTA, ("p", S(src))]}

